from typing import List

def numberOfEnclaves(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])

    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] == 0:
            return
        grid[x][y] = 0
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    # Mark all land cells connected to the boundary
    for i in range(n):
        dfs(i, 0)
        dfs(i, m - 1)

    for j in range(m):
        dfs(0, j)
        dfs(n - 1, j)

    # Count the remaining land cells
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                count += 1

    return count
